        assert(
            ret == 0 &&
            userRound == roundBefore &&
            usdcBalance == uint128(amount) &&
            unclaimedShares == 0 &&
            roundUsdcAfter >= roundUsdcBefore &&
            (!roundAdvanced || roundUsdcAfter == 0)
        );
    }

    receive() external payable {}
}

