contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 depositAmount, address claimer, address receiver, uint256 claimAmount) public payable {
        require(depositAmount > 0, "depositAmount must be positive");
        require(claimer != address(0), "claimer must not be zero");
        require(receiver != address(0), "receiver must not be zero");
        require(claimAmount > 0, "claimAmount must be positive");

        uint256 initialShares = c.unclaimedShares(claimer);
        require(initialShares >= claimAmount, "claimer must have enough unclaimed shares");

        uint256 receiverBefore = c.unclaimedShares(receiver);

        bool reverted;
        try c.claim(receiver, claimAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 receiverAfter = c.unclaimedShares(receiver);

        if (!reverted) {
            assert(receiverAfter == receiverBefore + claimAmount);
        } else {
            assert(receiverAfter == receiverBefore);
        }
    }

    receive() external payable {}
}

