    }

    function run(uint128 amount, address receiver, uint256 expectedRound) public payable {
        require(receiver != address(0), "receiver zero");
        require(amount > 0, "amount zero");
        require(expectedRound == c.currentRound(), "round mismatch");

        uint256 beforeUserBal = c.usdcBalance(receiver);
        uint256 beforeRoundBal = c.roundUsdcBalance();
        uint256 beforeRound = c.currentRound();

        vm_usdc_mint(address(this), amount);
        usdc_approve(address(c), type(uint256).max);

        c.depositUsdc(amount, receiver);

        uint256 afterUserBal = c.usdcBalance(receiver);
        uint256 afterRoundBal = c.roundUsdcBalance();
        uint256 afterRound = c.currentRound();

        assert(
            afterUserBal == beforeUserBal + amount &&
            afterRoundBal == beforeRoundBal + amount &&
            afterRound == beforeRound &&
            afterRound == expectedRound
        );
    }

    // minimal helpers to mint/approve USDC on the freshly deployed C
    function vm_usdc_mint(address to, uint256 amount) internal {
        (, bytes memory data) = address(c).call(
            abi.encodeWithSignature("usdc()")
        );
        require(data.length == 32, "no usdc getter");
        address usdc = abi.decode(data, (address));
        (bool ok, ) = usdc.call(abi.encodeWithSignature("transfer(address,uint256)", to, amount));
        require(ok, "mint failed");
    }

    function usdc_approve(address spender, uint256 amount) internal {
        (, bytes memory data) = address(c).call(
            abi.encodeWithSignature("usdc()")
        );
        require(data.length == 32, "no usdc getter");
        address usdc = abi.decode(data, (address));
        (bool ok, ) = usdc.call(abi.encodeWithSignature("approve(address,uint256)", spender, amount));
        require(ok, "approve failed");
    }
}

