contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address receiver, uint256 amount) public payable {
        require(receiver != address(0));
        require(amount > 0);

        uint256 beforeShares = c.unclaimedShares(msg.sender);
        require(amount == beforeShares);

        bool reverted;
        try c.claim(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterShares = c.unclaimedShares(msg.sender);

        bool zeroBefore = (beforeShares == 0);
        bool zeroAfter = (afterShares == 0);
        bool fullyDecremented = (afterShares == beforeShares - amount);

        assert(
            (zeroBefore && reverted) ||
            (!zeroBefore && !reverted && fullyDecremented && zeroAfter)
        );
    }

    receive() external payable {}
}
